// ---------- VEHICLE CONFIG ----------
const vin = "YOUR_VIN";
const model = "YOUR_MODEL";
const vehicleName = "BMW Vehicle";
const manufacturer = "BMW";

// ---------- HOME ZONE CONFIG ----------
const homeLatitude = 0.0;   // YOUR_HOME_LATITUDE
const homeLongitude = 0.0;  // YOUR_HOME_LONGITUDE
const homeRadiusMeters = 100;

function distanceMeters(lat1, lon1, lat2, lon2) {
    const R = 6371000;
    const toRad = deg => deg * Math.PI / 180;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 +
        Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) *
        Math.sin(dLon / 2) ** 2;
    return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

function toSnake(raw) {
    return raw
        .replace(/^vehicle\./i, "")
        .replace(/([a-z0-9])([A-Z])/g, "$1_$2")
        .replace(/[^a-zA-Z0-9]+/g, "_")
        .replace(/^_+|_+$/g, "")
        .toLowerCase();
}

function labelToken(token) {
    const t = token.toLowerCase();
    const map = {
        drivetrain: "Drivetrain",
        battery: "Battery",
        batterymanagement: "Battery Management",
        management: "Management",
        engine: "Engine",
        temperature: "Temperature",
        currentlocation: "Location",
        travelleddistance: "Travelled Distance",
        avgspeed: "Average Speed",
        hvsoc: "High Voltage",
        isopen: "Open",
        charging: "Charging",
        tire: "Tyre",
        tyres: "Tyre",
        pressure: "Pressure",
        row1: "Front",
        row2: "Rear",
        left: "Left",
        right: "Right",
        wheel: "Wheel",
        wheels: "Wheel",
        window: "Window",
        doors: "Door",
        door: "Door",
        soc: "State of Charge",
        target: "Target",
        frontleft: "Front Left",
        frontright: "Front Right",
        rearleft: "Rear Left",
        rearright: "Rear Right",
        front: "Front",
        rear: "Rear",
        location: "Location"
    };
    return map[t] || token.replace(/^./, c => c.toUpperCase());
}

function buildFriendlyName(raw) {
    const rawLower = raw.toLowerCase();

    if (rawLower.includes("row1.wheel.left")) return "Front Left Tyre Pressure";
    if (rawLower.includes("row1.wheel.right")) return "Front Right Tyre Pressure";
    if (rawLower.includes("row2.wheel.left")) return "Rear Left Tyre Pressure";
    if (rawLower.includes("row2.wheel.right")) return "Rear Right Tyre Pressure";

    if (rawLower.includes("isopen")) {
        const lower = raw.toLowerCase();
        let doorLocation = "Front";

        if (lower.includes("frontleft")) doorLocation = "Front Left";
        else if (lower.includes("frontright")) doorLocation = "Front Right";
        else if (lower.includes("rearleft")) doorLocation = "Rear Left";
        else if (lower.includes("rearright")) doorLocation = "Rear Right";

        return `${doorLocation} Door Open`;
    }

    const cleaned = raw
        .replace(/^vehicle\./i, "")
        .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
        .replace(/[._-]+/g, " ")
        .split(/\s+/)
        .filter(Boolean)
        .map(token => token.trim())
        .filter(token => !["vehicle", "header", "door", "doors"].includes(token.toLowerCase()));

    let friendly = cleaned.map(labelToken).join(" ");

    if (!friendly) {
        friendly = "Value";
    }

    if (rawLower.includes("pressuretarget")) {
        friendly += " Target";
    }

    return friendly;
}

// ---------- INPUT ----------
if (!msg || !msg.payload || !msg.payload.name) {
    node.warn("Missing payload.name, skipping discovery: " + JSON.stringify(msg && msg.payload));
    return null;
}

const rawName = msg.payload.name;
const value = msg.payload.value;
const unit = msg.payload.unit || null;

if (value === undefined) {
    node.warn("Missing payload.value for " + rawName);
    return null;
}

// ---------- VALUE TYPE DETECTION ----------
const isBoolean = typeof value === "boolean";
const isNumber  = typeof value === "number";
const isString  = typeof value === "string";

// ---------- DEVICE TRACKER (GPS location) ----------
if (rawName === "vehicle.currentLocation" && value && typeof value === "object") {
    const entity_id = "bmw_location";
    const configTopic = `homeassistant/device_tracker/${entity_id}/config`;
    const attributesTopic = `homeassistant/device_tracker/${entity_id}/attributes`;
    const stateTopic = `homeassistant/device_tracker/${entity_id}/state`;

    const configPayload = {
        name: "Location",
        unique_id: entity_id,
        has_entity_name: true,
        state_topic: stateTopic,
        json_attributes_topic: attributesTopic,
        source_type: "gps",
        device: {
            identifiers: [vin],
            name: vehicleName,
            manufacturer: manufacturer,
            model: model
        }
    };

    const attributesPayload = {
        latitude: value.latitude,
        longitude: value.longitude
    };
    if (value.altitude !== undefined) attributesPayload.altitude = value.altitude;
    if (value.heading  !== undefined) attributesPayload.course   = value.heading;

    const distance = distanceMeters(value.latitude, value.longitude, homeLatitude, homeLongitude);
    const statePayload = distance <= homeRadiusMeters ? "home" : "not_home";

    return [
        { topic: configTopic, payload: configPayload, retain: true },
        [
            { topic: attributesTopic, payload: attributesPayload, retain: true },
            { topic: stateTopic, payload: statePayload, retain: true }
        ]
    ];
}

// ---------- DOMAIN DETECTION ----------
let domain = "sensor";

if (isBoolean) {
    domain = "binary_sensor";
}

// ---------- CLEAN ENTITY ID ----------
const entity_id = `bmw_${toSnake(rawName)}`;

// ---------- MQTT DISCOVERY TOPICS ----------
const stateTopic  = `homeassistant/${domain}/${entity_id}/state`;
const configTopic = `homeassistant/${domain}/${entity_id}/config`;

// ---------- STATE CLASS ----------
let stateClass = null;

if (isNumber) {
    stateClass = "measurement";
}

if (rawName.toLowerCase().includes("travelleddistance")) {
    stateClass = "total_increasing";
}

if (rawName.toLowerCase().includes("pressuretarget")) {
    stateClass = null;
}

// ---------- DEVICE CLASS ----------
let deviceClass = null;

if (unit === "A"   && isNumber) deviceClass = "current";
if (unit === "kW"  && isNumber) deviceClass = "power";
if (unit === "kWh" && isNumber) deviceClass = "energy";
if (rawName.toLowerCase().includes("hvsoc")) {
    deviceClass = "battery";
}
if (rawName.includes("tire.pressure") && isNumber) deviceClass = "pressure";
if (rawName.includes("avgSpeed") && isNumber) deviceClass = "speed";
if (rawName.includes("travelledDistance") && isNumber) deviceClass = "distance";

if (domain === "binary_sensor") {
    if (rawName.includes("isOpen"))   deviceClass = "door";
    if (rawName.includes("charging")) deviceClass = "plug";
    if (rawName.includes(".window.")) deviceClass = "window";
}

// ---------- UNIT NORMALIZATION ----------
let normalizedUnit = unit;

if (unit) {
    const u = unit.toLowerCase();
    if (u === "kpa")     normalizedUnit = "kPa";
    if (u === "percent") normalizedUnit = "%";
    if (u === "km/h")   normalizedUnit = "km/h";
}

if (rawName.toLowerCase().includes("hvsoc")) {
    normalizedUnit = "%";
    stateClass = "measurement";
}

if (isString) {
    normalizedUnit = null;
    stateClass = null;
    deviceClass = null;
}

// ---------- FRIENDLY NAME ----------
const friendlyName = buildFriendlyName(rawName);

// ---------- DISCOVERY PAYLOAD ----------
const configPayload = {
    name: friendlyName,
    unique_id: entity_id,
    has_entity_name: true,
    state_topic: stateTopic,

    device_class: deviceClass || undefined,
    state_class: stateClass || undefined,
    unit_of_measurement: normalizedUnit || undefined,

    ...(domain === "binary_sensor"
        ? { payload_on: "ON", payload_off: "OFF" }
        : {}),

    device: {
        identifiers: [vin],
        name: vehicleName,
        manufacturer: manufacturer,
        model: model
    }
};

// ---------- STATE NORMALIZATION ----------
let statePayload = value;

if (domain === "binary_sensor") {
    statePayload = value === true ? "ON" : "OFF";
}

// ---------- OUTPUT TO MQTT ----------
return [
    {
        topic: configTopic,
        payload: configPayload,
        retain: true
    },
    {
        topic: stateTopic,
        payload: statePayload,
        retain: true
    }
];

// Make sure payload and data exist
if (!msg.payload || !msg.payload.data) {
    node.warn("No data field in payload, skipping: " + JSON.stringify(msg.payload));
    return null;
}

// Process every measurement in the data object
const data = msg.payload.data;
const entries = Object.entries(data || {});

if (entries.length === 0) {
    node.warn("Empty data object");
    return null;
}

// GPS fields arrive one at a time in separate messages (never bundled together),
// so the last known value of each is cached in node context and merged whenever
// any one of them updates.
const LOCATION_FIELD_RE = /currentLocation\.(latitude|longitude|heading|altitude)$/i;

const messages = [];
let locationUpdated = false;
const location = context.get("bmwLocation") || {};

for (const [key, measurement] of entries) {
    if (!measurement || measurement.value === undefined) {
        node.warn("Missing measurement fields in " + key);
        continue;
    }

    const locationMatch = key.match(LOCATION_FIELD_RE);
    if (locationMatch) {
        location[locationMatch[1].toLowerCase()] = Number(measurement.value);
        location.timestamp = measurement.timestamp;
        locationUpdated = true;
        continue;
    }

    messages.push({
        payload: {
            name: key,
            value: measurement.value,
            unit: measurement.unit,
            timestamp: measurement.timestamp
        }
    });
}

if (locationUpdated) {
    context.set("bmwLocation", location);

    if (location.latitude !== undefined && location.longitude !== undefined) {
        messages.push({
            payload: {
                name: "vehicle.currentLocation",
                value: {
                    latitude: location.latitude,
                    longitude: location.longitude,
                    heading: location.heading,
                    altitude: location.altitude
                },
                unit: null,
                timestamp: location.timestamp
            }
        });
    }
}

if (messages.length === 0) {
    return null;
}

return messages;
